  });
  const xs = resetLineXs(svg);
  assert.equal(xs.length, 40, "回溯受 guard<40 守卫截断为恰四十个点");
}
{
  // 非法 resetsAt / 非法 period 一律无重置线
  const base = {
    samples: [{ x: T0, y: 10 }, { x: T0 + 30 * MIN, y: 20 }],
    color: "#abc", lo: 0, hi: 100, dateOnly: false,
  };
  for (const bad of [
