  const e = esc;
  // 极差=0.5/3≈0.167 → norm=0.167/0.1=1.67 → <3.5 → step=2*0.1=0.2
  const tight = openCodeGoAdapter.formatPanel({
    entries: [mkEntry(0, { rolling: { percent: 1, resetsAt: undefined } }),
